package com.circlenet.domain.health;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="health_reports") public class HealthReportEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="user_id",nullable=false)Long userId;@Column(name="source_post_id")Long sourcePostId;@Column(name="report_name",nullable=false,length=200)String reportName;@Column(length=200)String laboratory;@Column(name="collected_on",nullable=false)LocalDate collectedOn;@Column(length=1000)String notes;@Column(name="created_at",nullable=false)Instant createdAt=Instant.now();public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public Long getSourcePostId(){return sourcePostId;}public void setSourcePostId(Long v){sourcePostId=v;}public String getReportName(){return reportName;}public void setReportName(String v){reportName=v;}public String getLaboratory(){return laboratory;}public void setLaboratory(String v){laboratory=v;}public LocalDate getCollectedOn(){return collectedOn;}public void setCollectedOn(LocalDate v){collectedOn=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public Instant getCreatedAt(){return createdAt;}}
